local _, ns = ...

-- Trilingual localization table:
--   English (enUS/enGB default fallback)
--   Portuguese (ptBR/ptPT)
--   Spanish (esES/esMX)
-- Respects the player's chosen language/textLocale in World of Warcraft Options.
local fallbackMemoCount = 0
local L = setmetatable({}, {
    __index = function(tbl, key)
        if type(key) ~= "string" then
            return key
        end
        local mapped = key
            :gsub("%f[%w]Clans%f[%W]", "Guilds")
            :gsub("%f[%w]Clan%f[%W]", "Guild")
            :gsub("%f[%w]CLANS%f[%W]", "GUILDS")
            :gsub("%f[%w]CLAN%f[%W]", "GUILD")
            :gsub("%f[%w]clans%f[%W]", "guilds")
            :gsub("%f[%w]clan%f[%W]", "guild")
        if #key <= 140 and fallbackMemoCount < 2500 then
            fallbackMemoCount = fallbackMemoCount + 1
            rawset(tbl, key, mapped)
        end
        return mapped
    end,
})

ns.L = L

local locale = (GetLocale and GetLocale()) or "enUS"
local textOpt = (C_CVar and C_CVar.GetCVar and C_CVar.GetCVar("textLocale")) or (GetCVar and GetCVar("textLocale"))
if type(textOpt) == "string" and textOpt ~= "" and textOpt ~= "system" then
    locale = textOpt
end

ns.detectedLocale = locale
ns.langOverridden = false
local langPref = type(SocialCentralDB) == "table" and type(SocialCentralDB.settings) == "table" and SocialCentralDB.settings.language
if langPref == "enUS" or langPref == "ptBR" or langPref == "esES" then
    locale = langPref
    ns.langOverridden = true
end

ns.activeLocale = locale
if locale == "ptBR" or locale == "ptPT" then
    ns.activeLangLabel = "Português"
elseif locale == "esES" or locale == "esMX" then
    ns.activeLangLabel = "Español"
else
    ns.activeLangLabel = "English"
end

