    L["Test Minimap Preview"] = "Probar Vista Previa en el Minimapa"
    L["Uncheck if you prefer to receive Private Room & Alliance alerts only in the top Toast stack or Conversations panel."] = "Desmarca si prefieres ver avisos de Salas Privadas y Alianza solo en las alertas superiores o en el panel de Conversaciones."
    L["Uncheck if you still want Whispers or Group previews during PvP matches."] = "Desmarca si aún deseas ver vistas previas de Susurros o Grupo durante partidas JcJ."
    L["Uncheck to disable minimap message previews completely without affecting your Conversations panel or unread counter badge."] = "Desmarca para desactivar por completo las vistas previas junto al minimapa sin afectar tu panel de Conversaciones ni el contador de no leídos."
    L["Whispers & Direct Chat"] = "Susurros y Chat Directo"
    L["You can also test specific channels anytime using '/sc preview whisper', 'bnet', 'group', 'guild', or 'setup'."] = "También puedes probar canales específicos en cualquier momento usando '/sc preview whisper', 'bnet', 'group', 'guild' o 'setup'."
    L["You can customize channels, duration, and dungeon/raid rules anytime in Settings -> Notifications."] = "Puedes personalizar canales, duración y filtros de mazmorra/banda en cualquier momento en Configuración -> Notificaciones."
